CREATE OR REPLACE FUNCTION public.save_company_details(p_name text, p_logo_url text, p_primary_color text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oid uuid := public.get_user_org_id(); BEGIN IF oid IS NULL OR NOT public.is_org_active(oid) OR NOT (public.is_org_admin(oid) OR public.has_role_in_org(auth.uid(),oid,'admin')) THEN RAISE EXCEPTION 'Only company admins can save company details'; END IF; IF length(trim(coalesce(p_name,'')))=0 THEN RAISE EXCEPTION 'Enter your company name'; END IF; IF p_primary_color IS NOT NULL AND p_primary_color !~ '^#[0-9a-fA-F]{6}$' THEN RAISE EXCEPTION 'Pick a valid brand colour'; END IF; IF p_logo_url IS NOT NULL AND p_logo_url NOT LIKE 'storage://customer-logos/'||oid::text||'/print-logos/%' AND p_logo_url IS DISTINCT FROM (SELECT logo_url FROM public.organisations WHERE id=oid) THEN RAISE EXCEPTION 'Upload a logo belonging to this company'; END IF; UPDATE public.organisations SET name=trim(p_name),logo_url=p_logo_url,primary_color=p_primary_color WHERE id=oid; INSERT INTO public.app_settings(org_id,key,value,updated_at) VALUES(oid,'org_branding',jsonb_build_object('company_name',trim(p_name)),now()) ON CONFLICT(org_id,key) DO UPDATE SET value=coalesce(app_settings.value,'{}'::jsonb)||jsonb_build_object('company_name',trim(p_name)),updated_at=now(); END; $$; REVOKE ALL ON FUNCTION public.save_company_details(text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_company_details(text,text,text) TO authenticated,service_role;